class ActionCompletion(enum.Enum):

    NOT_STARTED = 0

    COMPLETED = 1

    UNKNOWN = 2



class _UniffiFfiConverterTypeActionCompletion(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return ActionCompletion.NOT_STARTED
        if variant == 2:
            return ActionCompletion.COMPLETED
        if variant == 3:
            return ActionCompletion.UNKNOWN
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == ActionCompletion.NOT_STARTED:
            return
        if value == ActionCompletion.COMPLETED:
            return
        if value == ActionCompletion.UNKNOWN:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == ActionCompletion.NOT_STARTED:
            buf.write_i32(1)
        if value == ActionCompletion.COMPLETED:
            buf.write_i32(2)
        if value == ActionCompletion.UNKNOWN:
            buf.write_i32(3)





# DriverAuthorizationHostError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class DriverAuthorizationHostError(Exception):
    pass

_UniffiTempDriverAuthorizationHostError = DriverAuthorizationHostError

class DriverAuthorizationHostError:  # type: ignore

    class Failed(_UniffiTempDriverAuthorizationHostError):

        def __init__(self, reason):
            super().__init__(", ".join([
                "reason={!r}".format(reason),
            ]))
            self.reason = reason

        def __repr__(self):
            return "DriverAuthorizationHostError.Failed({})".format(str(self))
    _UniffiTempDriverAuthorizationHostError.Failed = Failed # type: ignore

DriverAuthorizationHostError = _UniffiTempDriverAuthorizationHostError # type: ignore
del _UniffiTempDriverAuthorizationHostError


class _UniffiFfiConverterTypeDriverAuthorizationHostError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return DriverAuthorizationHostError.Failed(
                _UniffiFfiConverterString.read(buf),
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, DriverAuthorizationHostError.Failed):
            _UniffiFfiConverterString.check_lower(value.reason)
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, DriverAuthorizationHostError.Failed):
            buf.write_i32(1)
            _UniffiFfiConverterString.write(value.reason, buf)



# DriverError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class DriverError(Exception):
    pass

_UniffiTempDriverError = DriverError

class DriverError:  # type: ignore

    class Configuration(_UniffiTempDriverError):

        def __init__(self, reason):
            super().__init__(", ".join([
                "reason={!r}".format(reason),
            ]))
            self.reason = reason

        def __repr__(self):
            return "DriverError.Configuration({})".format(str(self))
    _UniffiTempDriverError.Configuration = Configuration # type: ignore
    class InvalidArguments(_UniffiTempDriverError):

        def __init__(self, tool, reason):
            super().__init__(", ".join([
                "tool={!r}".format(tool),
                "reason={!r}".format(reason),
            ]))
            self.tool = tool
            self.reason = reason

        def __repr__(self):
            return "DriverError.InvalidArguments({})".format(str(self))
    _UniffiTempDriverError.InvalidArguments = InvalidArguments # type: ignore
    class Transport(_UniffiTempDriverError):

        def __init__(self, socket_path, reason):
            super().__init__(", ".join([
                "socket_path={!r}".format(socket_path),
                "reason={!r}".format(reason),
            ]))
            self.socket_path = socket_path
            self.reason = reason

        def __repr__(self):
            return "DriverError.Transport({})".format(str(self))
    _UniffiTempDriverError.Transport = Transport # type: ignore
    class Protocol(_UniffiTempDriverError):

        def __init__(self, reason):
            super().__init__(", ".join([
                "reason={!r}".format(reason),
            ]))
            self.reason = reason

        def __repr__(self):
            return "DriverError.Protocol({})".format(str(self))
    _UniffiTempDriverError.Protocol = Protocol # type: ignore
    class Tool(_UniffiTempDriverError):

        def __init__(self, tool, message, error_code):
            super().__init__(", ".join([
                "tool={!r}".format(tool),
                "message={!r}".format(message),
                "error_code={!r}".format(error_code),
            ]))
            self.tool = tool
            self.message = message
            self.error_code = error_code

        def __repr__(self):
            return "DriverError.Tool({})".format(str(self))
    _UniffiTempDriverError.Tool = Tool # type: ignore
    class Shutdown(_UniffiTempDriverError):

        def __init__(self):
            pass

        def __repr__(self):
            return "DriverError.Shutdown({})".format(str(self))
    _UniffiTempDriverError.Shutdown = Shutdown # type: ignore
    class RuntimeAlreadyExists(_UniffiTempDriverError):

        def __init__(self):
            pass

        def __repr__(self):
            return "DriverError.RuntimeAlreadyExists({})".format(str(self))
    _UniffiTempDriverError.RuntimeAlreadyExists = RuntimeAlreadyExists # type: ignore
    class Worker(_UniffiTempDriverError):

        def __init__(self, reason):
            super().__init__(", ".join([
                "reason={!r}".format(reason),
            ]))
            self.reason = reason

