class _UniffiFfiConverterTypeCuaDriver:
    @staticmethod
    def lift(value: int) -> CuaDriver:
        return CuaDriver._uniffi_make_instance(value)

    @staticmethod
    def check_lower(value: CuaDriver):
        if not isinstance(value, CuaDriver):
            raise TypeError("Expected CuaDriver instance, {} found".format(type(value).__name__))

    @staticmethod
    def lower(value: CuaDriver) -> ctypes.c_uint64:
        return value._uniffi_clone_handle()

    @classmethod
    def read(cls, buf: _UniffiRustBuffer) -> CuaDriver:
        ptr = buf.read_u64()
        if ptr == 0:
            raise InternalError("Raw handle value was null")
        return cls.lift(ptr)

    @classmethod
    def write(cls, value: CuaDriver, buf: _UniffiRustBuffer):
        buf.write_u64(cls.lower(value))


